def permute(s):
    if len(s) == 1:
        return [s]
    result = []
    for i, ch in enumerate(s):
        rest = s[:i] + s[i+1:]
        for p in permute(rest):
            result.append(ch + p)
    return result
print(len(permute('abcd')))

def ack(m, n):
    if m == 0:
        return n + 1
    elif n == 0:
        return ack(m - 1, 1)
    else:
        return ack(m - 1, ack(m, n - 1))
print(ack(2, 3))
